    if len(t) > len(s):
        return ""

    char_count = {}
    for char in t:
        char_count[char] = char_count.get(char, 0) + 1

    start, end = 0, 0
    min_length = float('inf')
    min_start = 0

    while end < len(s):
        current_char = s[end]
        if current_char in char_count:
